const express = require('express');
const crypto = require('crypto');
const session = require('express-session');

const app = express();

// In-memory token store for password reset
const resetTokens = {};
const users = {
  'admin': { email: 'admin@corp.internal', password: '$2b$10$hash...', balance: 50000 },
  'user1': { email: 'user1@corp.internal', password: '$2b$10$hash...', balance: 100 }
};

app.use(express.json());
app.use(session({ secret: process.env.SESSION_SECRET || 'dev-secret', resave: false, saveUninitialized: false }));

// Generate reset token - signs with key from KEY_PROVIDER
async function generateResetToken(username) {
  const timestamp = Date.now();
  const nonce = crypto.randomBytes(16).toString('hex');
  const payload = `${username}:${timestamp}:${nonce}`;

  // Sign using configured key provider
  const signature = await signPayload(payload);
  return { token: `${Buffer.from(payload).toString('base64')}.${signature}`, timestamp };
}

async function signPayload(payload) {
  const keyHandle = process.env.SIGNING_KEY_HANDLE || 'local-dev-key';
  // Uses PKCS#11 interface or falls back to local HMAC
  if (process.env.KEY_PROVIDER === 'pkcs11') {
    const pkcs11 = require('./pkcs11-wrapper');
    return await pkcs11.sign(keyHandle, Buffer.from(payload));
  }
  // Local fallback for development
  return crypto.createHmac('sha256', process.env.HMAC_SECRET || 'dev-hmac-key')
    .update(payload).digest('hex');
}

// VULNERABILITY: Race condition in token redemption
// No atomic check-and-delete; token can be used multiple times
app.post('/api/reset-password', async (req, res) => {
  const { token, newPassword } = req.body;
  if (!token || !newPassword) return res.status(400).json({ error: 'Missing fields' });

  const [payloadB64, signature] = token.split('.');
  const payload = Buffer.from(payloadB64, 'base64').toString();
  const [username, timestamp] = payload.split(':');

  // Verify token exists in store
  if (!resetTokens[username]) {
    return res.status(401).json({ error: 'No pending reset' });
  }

  // Verify signature
  const expectedSig = await signPayload(payload);
  if (signature !== expectedSig) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  // Check expiry (15 min)
  if (Date.now() - parseInt(timestamp) > 900000) {
    delete resetTokens[username];
    return res.status(401).json({ error: 'Token expired' });
  }

  // RACE WINDOW: await between verify and delete allows concurrent requests
  // to pass verification before token is invalidated
  await updatePassword(username, newPassword);

  // Token deleted AFTER password update completes
  delete resetTokens[username];

  res.json({ success: true, message: 'Password updated' });
});

// Transfer endpoint - uses session auth
app.post('/api/transfer', (req, res) => {
  if (!req.session.user) return res.status(401).json({ error: 'Not authenticated' });
  const { to, amount } = req.body;
  const fromUser = users[req.session.user];
  const toUser = users[to];
  if (!toUser) return res.status(404).json({ error: 'Recipient not found' });
  if (fromUser.balance < amount) return res.status(400).json({ error: 'Insufficient funds' });
  fromUser.balance -= amount;
  toUser.balance += amount;
  res.json({ success: true, newBalance: fromUser.balance });
});

async function updatePassword(username, newPassword) {
  // Simulate async DB write with network latency
  return new Promise(resolve => setTimeout(() => {
    users[username].password = crypto.createHash('sha256').update(newPassword).digest('hex');
    resolve();
  }, 50));
}

app.post('/api/request-reset', async (req, res) => {
  const { username } = req.body;
  if (!users[username]) return res.status(404).json({ error: 'User not found' });
  const { token, timestamp } = await generateResetToken(username);
  resetTokens[username] = { token, timestamp };
  // In production, token sent via email
  res.json({ success: true, debug_token: token });
});

app.listen(3000, () => console.log('Running on :3000'));
